mapper.select:
SELECT q.no,q.title,q.image,q.answer,o.option1,o.option2,o.option3,o.option4,q.type,q.theme,q.score
FROM (
	SELECT *
	FROM EXAM_QUESTION


				WHERE no IN(
				    SELECT question_no
				    FROM SCHEDULED_EXAM_MAP
				    WHERE exam_no=#{exam_no}
				)


				WHERE theme=#{theme}
				ORDER BY DBMS_RANDOM.VALUE


	) q
	LEFT JOIN EXAM_OPTION o ON q.no=o.question_no

		WHERE ROWNUM <= #{count}

	ORDER BY q.no

SELECT no, member_id, exam_no, theme, starttime
FROM EXAM_ENROLLMENT
WHERE member_id=#{member_id}
AND endtime IS NULL


		AND exam_no=#{exam_no}


		AND theme=#{theme}
		AND exam_no IS NULL


AND starttime>=SYSDATE-(120/(24*60))
AND ROWNUM=1
ORDER BY starttime DESC

SELECT title
FROM SCHEDULED_EXAM
WHERE no=#{examNo}

mapper.update:
UPDATE exam_enrollment
SET endtime=#{endtime},
    totalscore=#{totalscore},
    status=#{status}
WHERE no=#{no}

UPDATE exam_user_answer
SET grader_id=#{graderId}
WHERE no=#{answerNo}
  AND is_correct='W'
  AND grader_id IS NULL

UPDATE exam_user_answer
SET grader_id=NULL
WHERE no=#{answerNo}
	AND grader_id=#{graderId}
	AND is_correct='W'

UPDATE exam_user_answer
SET score=#{score},
    is_correct=CASE WHEN #{score} > 0 THEN 'Y' ELSE 'N' END,
    graded_at=SYSDATE
WHERE no=#{answerNo}
  AND grader_id=#{graderId}

UPDATE exam_enrollment
SET totalscore=(
	SELECT NVL(SUM(score), 0)
	FROM exam_user_answer
	WHERE enrollment_no=#{enrollmentNo}
),
    status='COMPLETE'
WHERE no=#{enrollmentNo}
